// ── PARTS DATA ──
let PARTS_DATA = DATA.parts;   /* from Golden /v1/service/catalog at mount (build-golden-support.js) */

// ── PRICING: dealer price + MSRP (MSRP = dealer price x 2) ──
function formatDealerMsrp(price) {
  var p = Number(price);
  if (!isFinite(p) || p <= 0) {
    return { dealerText: 'Call', msrpText: '', cell: 'Call', inline: 'Call' };
  }
  var msrp = p * 2;
  var dealerText = '$' + p.toFixed(2);
  var msrpText = '$' + msrp.toFixed(2);
  return {
    dealerText: dealerText,
    msrpText: msrpText,
    cell: 'Dealer ' + dealerText + ' · Calc. retail ' + msrpText,
    inline: 'Dealer ' + dealerText + ' · Calc. retail ' + msrpText
  };
}

// ── TAB NAVIGATION ──
function showTab(tabId, btn) {
  ROOT.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
  ROOT.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
  ROOT.getElementById('tab-' + tabId).classList.add('active');
  btn.classList.add('active');
  if (tabId === 'parts') { updateModelSelect(); renderParts(); }
  if (tabId === 'videos') { renderVideos(); }
}

// ── PARTS LOOKUP + CART ──
let cart = []; // { partNum, desc, price, qty, model }
// Owner 2026-11-23: a part without a valid positive dealer price is never orderable. A stale cart entry is dropped here and the
// server refuses it again (send-parts / signed order validation).
function pruneCart() { cart = cart.filter(c => c && Number.isFinite(Number(c.price)) && Number(c.price) > 0); }

function updateModelSelect() {
  const line = ROOT.getElementById('productLine').value;
  const modelSel = ROOT.getElementById('modelSelect');
  const catSel = ROOT.getElementById('categorySelect');
  const col3 = ROOT.getElementById('col3header');

  if (line === 'lift_chair') {
    modelSel.style.display = 'none';
    catSel.style.display = '';
    col3.textContent = 'Category';
  } else {
    modelSel.style.display = '';
    catSel.style.display = 'none';
    col3.textContent = 'Model';
    modelSel.innerHTML = '<option value="">All Models</option>';
    Object.keys(PARTS_DATA[line]).forEach(m => {
      const opt = document.createElement('option');
      opt.value = m; opt.textContent = m;
      modelSel.appendChild(opt);
    });
  }
}

function renderParts() {
  const line = ROOT.getElementById('productLine').value;
  const search = ROOT.getElementById('partsSearch').value.toLowerCase();
  const modelSel = ROOT.getElementById('modelSelect');
  const catSel = ROOT.getElementById('categorySelect');
  const tbody = ROOT.getElementById('partsBody');
  const countEl = ROOT.getElementById('resultsCount');

  let parts = [];

  if (line === 'lift_chair') {
    const cat = catSel.value;
    parts = PARTS_DATA.lift_chair.filter(p => {
      const matchCat = !cat || p.cat === cat;
      const matchSearch = !search || p.item.toLowerCase().includes(search) || p.desc.toLowerCase().includes(search);
      return matchCat && matchSearch;
    }).map(p => ({ partNum: p.item, desc: p.desc, price: p.price, model: p.cat }));
  } else {
    const selModel = modelSel ? modelSel.value : '';
    const models = selModel ? [selModel] : Object.keys(PARTS_DATA[line]);
    models.forEach(m => {
      PARTS_DATA[line][m].forEach(p => {
        const matchSearch = !search || p.part.toLowerCase().includes(search) || p.desc.toLowerCase().includes(search);
        if (matchSearch) parts.push({ partNum: p.part, desc: p.desc, price: p.price, model: m });
      });
    });
  }

  if (parts.length === 0) {
    tbody.innerHTML = '<tr><td colspan="6" class="no-results">No parts found. Try a different search term or category.</td></tr>';
    countEl.innerHTML = 'No results found.';
    return;
  }

  tbody.innerHTML = parts.map(p => {
    const inCart = cart.find(c => c.partNum === p.partNum);
    const btnClass = inCart ? 'add-to-cart-btn added' : 'add-to-cart-btn';
    const btnText = inCart ? '✓ Added' : '+ Add';
    const safeDesc = p.desc.replace(/'/g, "\\'");
    return `<tr id="row-${p.partNum.replace(/[^a-zA-Z0-9]/g,'-')}">
      <td><span class="part-num">${p.partNum}</span></td>
      <td>${p.desc}</td>
      <td><span class="cat-badge">${p.model}</span></td>
      <td class="price-cell">${formatDealerMsrp(p.price).cell}</td>
      <td><input class="qty-input-inline" type="number" min="1" value="1" id="qty-${p.partNum.replace(/[^a-zA-Z0-9]/g,'-')}"></td>
      <td><button class="${btnClass}" id="btn-${p.partNum.replace(/[^a-zA-Z0-9]/g,'-')}"
          onclick="GSV.addToCart('${p.partNum}', '${safeDesc}', ${p.price}, '${p.model}')">
        ${btnText}
      </button></td>
    </tr>`;
  }).join('');

  countEl.innerHTML = `Showing <strong>${parts.length}</strong> part${parts.length !== 1 ? 's' : ''} — click <strong>+ Add</strong> to add to your order cart`;
}

function addToCart(partNum, desc, price, model) {
  if (!(Number(price) > 0)) return;   // never add an unpriced part
  const safeId = partNum.replace(/[^a-zA-Z0-9]/g, '-');
  const qtyEl = ROOT.getElementById('qty-' + safeId);
  const qty = qtyEl ? Math.max(1, parseInt(qtyEl.value) || 1) : 1;

  const existing = cart.find(c => c.partNum === partNum);
  if (existing) {
    existing.qty += qty;
  } else {
    cart.push({ partNum, desc, price, qty, model });
  }

  // Update button
  const btn = ROOT.getElementById('btn-' + safeId);
  if (btn) {
    btn.className = 'add-to-cart-btn added';
    btn.textContent = '✓ Added';
  }

  updateCartUI();
}

function updateCartUI() {
  pruneCart();
  const total = cart.reduce((sum, c) => sum + c.price * c.qty, 0);
  const count = cart.reduce((sum, c) => sum + c.qty, 0);

  // Hero stat
  ROOT.getElementById('cartHeroCount').textContent = count;

  // Cart bar
  const bar = ROOT.getElementById('cartBar');
  bar.style.display = cart.length > 0 ? 'flex' : 'none';
  ROOT.getElementById('cartCountBadge').textContent = `${count} item${count !== 1 ? 's' : ''}`;
  ROOT.getElementById('cartTotalBar').textContent = '$' + total.toFixed(2);

  renderCartPanel();
}

function renderCartPanel() {
  const wrap = ROOT.getElementById('cartItemsWrap');
  const footer = ROOT.getElementById('cartFooter');
  const total = cart.reduce((sum, c) => sum + c.price * c.qty, 0);

  if (cart.length === 0) {
    wrap.innerHTML = '<div class="cart-empty-msg">Your cart is empty. Search for parts below and click + Add to add them here.</div>';
    footer.style.display = 'none';
    return;
  }

  wrap.innerHTML = `<table class="cart-items-table">
    <thead>
      <tr>
        <th>Part Number</th>
        <th>Description</th>
        <th>Model / Category</th>
        <th>Unit Price</th>
        <th>Qty</th>
        <th>Notes / Color / Special Request</th>
        <th>Line Total</th>
        <th></th>
      </tr>
    </thead>
    <tbody>
      ${cart.map((c, i) => `<tr>
        <td><span class="part-num">${c.partNum}</span></td>
        <td>${c.desc}</td>
        <td><span class="cat-badge">${c.model}</span></td>
        <td class="price-cell">${formatDealerMsrp(c.price).cell}</td>
        <td class="cart-qty-cell">
          <input type="number" min="1" value="${c.qty}"
            onchange="GSV.updateCartQty(${i}, this.value)">
        </td>
        <td>
          <textarea class="cart-notes-input" rows="2"
            placeholder="e.g. Buff fabric, left-hand side, walnut finish..."
            onblur="GSV.updateCartNote(${i}, this.value)"
          >${c.notes || ''}</textarea>
        </td>
        <td class="price-cell">${formatDealerMsrp(c.price * c.qty).cell}</td>
        <td><button class="cart-remove-btn" onclick="GSV.removeFromCart(${i})">×</button></td>
      </tr>`).join('')}
    </tbody>
  </table>`;

  footer.style.display = 'flex';
  ROOT.getElementById('cartTotalFooter').textContent = '$' + total.toFixed(2);
}

function updateCartQty(index, val) {
  const qty = Math.max(1, parseInt(val) || 1);
  cart[index].qty = qty;
  updateCartUI();
}

function updateCartNote(index, val) {
  cart[index].notes = val.trim();
}

function removeFromCart(index) {
  const partNum = cart[index].partNum;
  cart.splice(index, 1);
  // Reset button in table if visible
  const safeId = partNum.replace(/[^a-zA-Z0-9]/g, '-');
  const btn = ROOT.getElementById('btn-' + safeId);
  if (btn) { btn.className = 'add-to-cart-btn'; btn.textContent = '+ Add'; }
  updateCartUI();
}

function clearCart() {
  if (!confirm('Clear all items from your cart?')) return;
  cart = [];
  // Reset all visible add buttons
  ROOT.querySelectorAll('.add-to-cart-btn.added').forEach(btn => {
    btn.className = 'add-to-cart-btn';
    btn.textContent = '+ Add';
  });
  ROOT.getElementById('cartPanel').classList.remove('open');
  updateCartUI();
}

function toggleCartPanel() {
  ROOT.getElementById('cartPanel').classList.toggle('open');
  renderCartPanel();
}

function proceedToOrderForm() {
  if (cart.length === 0) { alert('Your cart is empty.'); return; }

  const total = cart.reduce((sum, c) => sum + c.price * c.qty, 0);

  // Build readable cart summary for email
  const summaryLines = cart.map(c =>
    `${c.partNum} | ${c.desc} | ${c.model} | $${c.price.toFixed(2)} x ${c.qty} = $${(c.price * c.qty).toFixed(2)}${c.notes ? ' | Note: ' + c.notes : ''}`
  ).join('\n');
  ROOT.getElementById('cartSummaryField').value = summaryLines;
  ROOT.getElementById('estimatedTotalField').value = '$' + total.toFixed(2);

  // Build order summary table displayed in the form
  ROOT.getElementById('orderSummaryTable').innerHTML = `
    <div class="parts-table-wrap">
      <table class="parts-table">
        <thead>
          <tr>
            <th>Part Number</th>
            <th>Description</th>
            <th>Model / Category</th>
            <th>Unit Price</th>
            <th>Qty</th>
            <th>Notes / Special Request</th>
            <th>Line Total</th>
          </tr>
        </thead>
        <tbody>
          ${cart.map(c => `<tr>
            <td><span class="part-num">${c.partNum}</span></td>
            <td>${c.desc}</td>
            <td><span class="cat-badge">${c.model}</span></td>
            <td class="price-cell">${formatDealerMsrp(c.price).cell}</td>
            <td>${c.qty}</td>
            <td style="font-size:12px;color:var(--slate);font-style:${c.notes ? 'normal' : 'italic'};">
              ${c.notes || '<span style="color:#CCC;">—</span>'}
            </td>
            <td class="price-cell">${formatDealerMsrp(c.price * c.qty).cell}</td>
          </tr>`).join('')}
          <tr style="background:var(--mist);">
            <td colspan="6" style="text-align:right;font-weight:700;padding:10px 16px;">Estimated Total</td>
            <td class="price-cell" style="font-size:15px;">$${total.toFixed(2)}</td>
          </tr>
        </tbody>
      </table>
    </div>`;

  // Show form, hide cart panel
  ROOT.getElementById('cartPanel').classList.remove('open');
  ROOT.getElementById('orderFormCard').style.display = 'block';
  ROOT.getElementById('orderFormCard').scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function backToCart() {
  ROOT.getElementById('orderFormCard').style.display = 'none';
  ROOT.getElementById('cartPanel').classList.add('open');
  renderCartPanel();
}

function updateOrderRouting() {
  const cat = ROOT.getElementById('orderProductCategory').value;
  const hint = ROOT.getElementById('orderRoutingHint');
  if (!cat) { hint.style.display = 'none'; return; }
  if (cat === 'Power Lift Recliner') {
    hint.style.display = 'block';
    hint.style.background = 'var(--blue-bg)';
    hint.style.color = 'var(--blue)';
    hint.style.border = '1px solid #c3d9f5';
    hint.innerHTML = '📧 Order will be sent to <strong>liftchairparts@goldentech.com</strong>';
  } else {
    hint.style.display = 'block';
    hint.style.background = 'var(--green-bg)';
    hint.style.color = 'var(--green)';
    hint.style.border = '1px solid #b2dfc5';
    hint.innerHTML = '📧 Order will be sent to <strong>mobilityparts@goldentech.com</strong>';
  }
}

function submitPartsOrder(e) {
  e.preventDefault();
  const form = ROOT.getElementById('partsOrderForm');
  const cat = ROOT.getElementById('orderProductCategory').value;

  if (!cat) { alert('Please select a product category.'); return; }

  const endpoint = cat === 'Power Lift Recliner' ? ENDPOINTS.lift_chair : ENDPOINTS.mobility;

  if (false) {
    alert('⚠️ Formspree endpoints not yet configured. Replace xkoaapvk and xkoaapvk in the script.');
    return;
  }

  const submitBtn = form.querySelector('.submit-btn');
  submitBtn.disabled = true;
  submitBtn.textContent = 'Sending...';

  fetch(endpoint, {
    method: 'POST',
    body: new FormData(form),
    headers: { 'Accept': 'application/json' }
  }).then(r => {
    if (r.ok) {
      form.style.display = 'none';
      const dest = cat === 'Power Lift Recliner' ? 'liftchairparts@goldentech.com' : 'mobilityparts@goldentech.com';
      const msg = ROOT.getElementById('orderSuccessMsg');
      msg.querySelector('span').textContent =
        `Your parts order has been submitted to ${dest}. We'll confirm availability and pricing within 1 business day.`;
      msg.style.display = 'flex';
      cart = [];
      updateCartUI();
    } else {
      submitBtn.disabled = false;
      submitBtn.innerHTML = '📤 Submit Parts Order';
      alert('Submission error. Please try again.');
    }
  }).catch(() => {
    submitBtn.disabled = false;
    submitBtn.innerHTML = '📤 Submit Parts Order';
    alert('Network error. Please try again.');
  });
}

