let partRowCount = 1;

function addPartRow() {
  partRowCount++;
  const div = document.createElement('div');
  div.className = 'part-row';
  div.innerHTML = `
    <input type="text" name="part_num_${partRowCount}" placeholder="Part #">
    <input type="text" name="part_desc_${partRowCount}" placeholder="Description (optional)">
    <input type="number" name="part_qty_${partRowCount}" placeholder="1" min="1" value="1">
    <button type="button" class="remove-row-btn" onclick="GSV.removePartRow(this)">×</button>
  `;
  ROOT.getElementById('partRows').appendChild(div);
}

function removePartRow(btn) {
  const rows = ROOT.querySelectorAll('#partRows .part-row');
  if (rows.length > 1) btn.closest('.part-row').remove();
}

// ── FORM ROUTING ──
// Two Formspree forms — one per destination email.
// Step 1: Create two forms at formspree.io
//   Form A → liftchairparts@goldentech.com  → replace xkoaapvk below
//   Form B → mobilityparts@goldentech.com   → replace xkoaapvk below
const ENDPOINTS = {
  lift_chair: 'https://formspree.io/f/xkoaapvk',
  mobility:   'https://formspree.io/f/xkoaapvk'
};

function getEndpoint() {
  const cat = ROOT.getElementById('productCategorySelect').value;
  return cat === 'Power Lift Recliner' ? ENDPOINTS.lift_chair : ENDPOINTS.mobility;
}

function updateRoutingHint() {
  const cat = ROOT.getElementById('productCategorySelect').value;
  const hint = ROOT.getElementById('routingHint');
  if (!cat) { hint.style.display = 'none'; return; }

  if (cat === 'Power Lift Recliner') {
    hint.style.display = 'block';
    hint.style.background = 'var(--blue-bg)';
    hint.style.color = 'var(--blue)';
    hint.style.border = '1px solid #c3d9f5';
    hint.innerHTML = '📧 Request will be sent to <strong>liftchairparts@goldentech.com</strong>';
  } else {
    hint.style.display = 'block';
    hint.style.background = 'var(--green-bg)';
    hint.style.color = 'var(--green)';
    hint.style.border = '1px solid #b2dfc5';
    hint.innerHTML = '📧 Request will be sent to <strong>mobilityparts@goldentech.com</strong>';
  }
}

function submitRequest(e) {
  e.preventDefault();
  const form = ROOT.getElementById('serviceRequestForm');
  const cat = ROOT.getElementById('productCategorySelect').value;

  if (!cat) {
    alert('Please select a product category before submitting.');
    return;
  }

  const endpoint = getEndpoint();

  // Safety check — remind to configure endpoints
  if (false) {
    alert('⚠️ Form endpoints not yet configured. Replace xkoaapvk and xkoaapvk in the script with your Formspree form IDs.');
    return;
  }

  const submitBtn = form.querySelector('.submit-btn');
  submitBtn.disabled = true;
  submitBtn.textContent = 'Sending...';

  const data = new FormData(form);

  fetch(endpoint, {
    method: 'POST',
    body: data,
    headers: { 'Accept': 'application/json' }
  }).then(r => {
    if (r.ok) {
      form.style.display = 'none';
      const msg = ROOT.getElementById('successMsg');
      const dest = cat === 'Power Lift Recliner'
        ? 'liftchairparts@goldentech.com'
        : 'mobilityparts@goldentech.com';
      msg.querySelector('span').textContent =
        `Your request has been submitted to ${dest}. We'll follow up within 1 business day. Check your email for a confirmation copy.`;
      msg.style.display = 'flex';
    } else {
      submitBtn.disabled = false;
      submitBtn.innerHTML = '📤 Submit Request';
      alert('Submission error. Please try again or contact us directly.');
    }
  }).catch(() => {
    submitBtn.disabled = false;
    submitBtn.innerHTML = '📤 Submit Request';
    alert('Network error. Please try again.');
  });
}

