let activeVideoFilter = 'all';

function setVideoFilter(cat, btn) {
  activeVideoFilter = cat;
  ROOT.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  renderVideos();
}

function filterVideos() { renderVideos(); }

function renderVideos() {
  const search = ROOT.getElementById('videoSearch').value.toLowerCase();
  const grid = ROOT.getElementById('videoGrid');
  const catLabels = {
    'lift-chair': 'Lift Chair',
    'scooter': 'Scooter',
    'power-chair': 'Power Chair',
    'general': 'General'
  };

  const filtered = VIDEOS.filter(v => {
    const matchCat = activeVideoFilter === 'all' || v.id === activeVideoFilter;
    const matchSearch = !search || v.title.toLowerCase().includes(search) || v.desc.toLowerCase().includes(search);
    return matchCat && matchSearch;
  });

  if (filtered.length === 0) {
    grid.innerHTML = '<p style="color:var(--slate);font-size:14px;padding:20px 0;">No videos match your search.</p>';
    return;
  }

  grid.innerHTML = filtered.map(v => `
    <a class="video-card" href="${v.url}" target="_blank" style="text-decoration:none;">
      <div class="video-thumb">
        <img src="${v.thumb}" alt="${v.title}" loading="lazy"
             onerror="this.style.display='none';this.parentElement.style.background='var(--charcoal)';">
        <div class="play-btn">▶</div>
        <span class="video-cat-badge">${catLabels[v.id] || v.id}</span>
      </div>
      <div class="video-info">
        <h4>${v.title}</h4>
        <p>${v.desc}</p>
      </div>
    </a>
  `).join('');
}

